import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, color, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, CylinderGeometry, DirectionalLight, AmbientLight, Color, DoubleSide } = ctx.THREE;

  const COLORS = config.intent?.visualSpec?.colors ?? {};
  const BG = COLORS.background ?? '#0b0b10';
  const G0 = COLORS.gradientStops?.[0]?.hex ?? '#191921';
  const G1 = COLORS.gradientStops?.[1]?.hex ?? '#121218';
  const PAPER = COLORS.paper ?? '#e8ecf2';
  const ACCENT = COLORS.accent ?? '#ff2a38';
  const BORDER = '#26262f';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const root = new Group();
  root.name = 'feature-triptych';

  const timelines = [];
  const disposables = [];

  // ---- Backdrop stage ----
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const cTop = color(G0);
    const cBot = color(G1);
    const gy = uv().y;
    bgMat.colorNode = mix(cBot, cTop, gy);
  }
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.set(0, 0, -2.5);
  root.add(bg);
  disposables.push(bgGeo, bgMat);

  // ---- Lights (node-local rim/key; scene provides ambient+key) ----
  const key = new DirectionalLight(0xffffff, 1.15);
  key.position.set(-3, 3.5, 3);
  root.add(key);

  const rim = new DirectionalLight(new Color(ACCENT), 0.7);
  rim.position.set(3, -1.5, 2);
  root.add(rim);

  const fill = new AmbientLight(0xffffff, 0.45);
  root.add(fill);

  // ---- Card layout ----
  const CARD_W = 1.5;
  const CARD_H = 1.9;
  const GAP = 0.25;
  const rowTotal = CARD_W * 3 + GAP * 2;
  const startX = -rowTotal / 2 + CARD_W / 2;

  // group text items into triples
  const cards = [];
  for (let i = 0; i < 3; i++) {
    const base = i * 3;
    cards.push({
      glyph: items[base]?.text ?? String(i + 1).padStart(2, '0'),
      title: items[base + 1]?.text ?? '',
      body: items[base + 2]?.text ?? '',
    });
  }

  const cardObjects = [];

  cards.forEach((data, i) => {
    const cardGroup = new Group();
    const cx = startX + i * (CARD_W + GAP);
    cardGroup.position.set(cx, 0, 0);

    // contact shadow plane
    const shGeo = new PlaneGeometry(CARD_W * 1.15, CARD_H * 0.5);
    const shMat = new MeshBasicNodeMaterial();
    shMat.transparent = true;
    shMat.depthWrite = false;
    {
      const d = uv().distance(vec3(0.5, 0.5, 0).xy);
      const a = mix(0.5, 0.0, d.mul(2.0)).clamp(0, 0.5);
      shMat.colorNode = vec4(0, 0, 0, 1);
      shMat.opacityNode = a;
    }
    const shadow = new Mesh(shGeo, shMat);
    shadow.rotation.x = -Math.PI / 2 * 0.0;
    shadow.position.set(0, -CARD_H / 2 - 0.05, -0.05);
    cardGroup.add(shadow);
    disposables.push(shGeo, shMat);

    // card body (extruded box)
    const bodyGeo = new BoxGeometry(CARD_W, CARD_H, 0.08);
    const bodyMat = new MeshStandardNodeMaterial();
    bodyMat.roughness = 0.6;
    bodyMat.metalness = 0.25;
    bodyMat.clearcoat = 0.15;
    {
      const cTop = color(G0);
      const cBot = color(G1);
      const border = color(BORDER);
      const u = uv();
      const ramp = mix(cBot, cTop, u.y);
      // hairline border via edge distance
      const edgeX = u.x.sub(0.5).abs();
      const edgeY = u.y.sub(0.5).abs();
      const edge = edgeX.max(edgeY);
      const bMask = edge.step(0.485).oneMinus();
      bodyMat.colorNode = mix(ramp, border, bMask);
    }
    const cardMesh = new Mesh(bodyGeo, bodyMat);
    cardGroup.add(cardMesh);
    disposables.push(bodyGeo, bodyMat);

    // icon seat: machined disc
    const discGeo = new CylinderGeometry(0.2, 0.2, 0.05, 48);
    const discMat = new MeshStandardNodeMaterial();
    discMat.color = new Color('#2a2a34');
    discMat.roughness = 0.55;
    discMat.metalness = 0.5;
    discMat.clearcoat = 0.2;
    const disc = new Mesh(discGeo, discMat);
    disc.rotation.x = Math.PI / 2;
    const seatY = CARD_H / 2 - 0.375 - 0.2;
    disc.position.set(0, seatY, 0.06);
    cardGroup.add(disc);
    disposables.push(discGeo, discMat);

    // glyph text on disc
    const glyph = ctx.fontAtlas.createText(data.glyph, {
      fontSize: 40,
      color: ACCENT,
      align: 'center',
    });
    glyph.position.set(0, seatY, 0.1);
    cardGroup.add(glyph);

    // title
    const title = ctx.fontAtlas.createText(data.title, {
      fontSize: 40,
      color: PAPER,
      align: 'center',
      maxWidthPx: 260,
    });
    title.position.set(0, seatY - 0.2 - 0.25, 0.06);
    cardGroup.add(title);

    // body
    const body = ctx.fontAtlas.createText(data.body, {
      fontSize: 24,
      color: '#a8adba',
      align: 'center',
      maxWidthPx: 240,
      letterSpacingPx: 0,
    });
    body.position.set(0, seatY - 0.2 - 0.25 - 0.35, 0.06);
    cardGroup.add(body);

    root.add(cardGroup);

    cardObjects.push({ group: cardGroup, shadow, discMat, index: i });
  });

  // ---- Entrance: stagger fade-up ----
  const introTl = gsap.timeline();
  cardObjects.forEach((c, i) => {
    c.group.position.y = -0.2;
    introTl.fromTo(
      c.group.position,
      { y: -0.2 },
      { y: 0, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
    introTl.fromTo(
      c.group.scale,
      { x: 0.98, y: 0.98, z: 0.98 },
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
      i * 0.08
    );
  });
  timelines.push(introTl);

  // ---- Idle breathing (single slow transform) ----
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(root.position, { y: 0.02, duration: 3.5, ease: 'sine.inOut' });
  timelines.push(idleTl);

  // ---- Hover handlers ----
  function hoverCard(idx, on) {
    const c = cardObjects[idx];
    if (!c) return;
    gsap.to(c.group.position, {
      y: on ? 0.06 : 0,
      z: on ? 0.12 : 0,
      duration: 0.18,
      ease: 'power2.out',
    });
    gsap.to(c.shadow.scale, {
      x: on ? 1.18 : 1,
      y: on ? 1.18 : 1,
      duration: 0.18,
      ease: 'power2.out',
    });
  }

  root.userData.handlers = {
    pointerover: (e) => {
      const idx = e?.object?.userData?.cardIndex ?? 0;
      hoverCard(idx, true);
    },
    pointerout: (e) => {
      const idx = e?.object?.userData?.cardIndex ?? 0;
      hoverCard(idx, false);
    },
    click: () => {
      ctx.emit?.('navigate', { to: 'hub-features' });
    },
  };

  // tag meshes for hover routing
  cardObjects.forEach((c) => {
    c.group.traverse((o) => {
      o.userData.cardIndex = c.index;
    });
  });

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    disposables.forEach((d) => d.dispose && d.dispose());
    root.traverse((o) => {
      if (o.geometry && o.geometry.dispose) o.geometry.dispose();
      if (o.material && o.material.dispose) o.material.dispose();
    });
  };

  return root;
}
